@property
def units(self) -> Tuple[str, str]:
    """
    List of dimension units of the CRS.

    The ordering of the units is intended to reflect the :py:class:`numpy.ndarray` axis order of the
    loaded raster.
    """
    if self.geographic:
        return "degrees_north", "degrees_east"

    if self.projected:
        # Handle compound CRS by taking the first two spatial axes (typically easting, northing)
        axis_info = self._crs.axis_info
        if len(axis_info) >= 2:
            # Take the first two axes which should be the spatial dimensions
            x, y = axis_info[0], axis_info[1]
            return x.unit_name, y.unit_name
        else:
            # Fallback for unexpected cases
            raise ValueError("Expected at least 2 axes in projected CRS")

    raise ValueError("Neither projected nor geographic")  # pragma: no cover
